import { useEffect, useRef } from 'react';
import './About.css';

export default function About() {
  const ref = useRef(null);
  const cardRef = useRef(null);

  /* reveal on scroll */
  useEffect(() => {
    const obs = new IntersectionObserver(
      ([e]) => { if (e.isIntersecting) { ref.current?.classList.add('on'); obs.disconnect(); } },
      { threshold: 0.15 }
    );
    if (ref.current) obs.observe(ref.current);
    return () => obs.disconnect();
  }, []);

  /* elastic lanyard */
  useEffect(() => {
    const card = cardRef.current;
    const rope = document.querySelector('.rope-line');
    const ropeThrough = document.querySelector('.rope-through');
    if (!card || !rope) return;

    let x = 0, y = 0;
    let vx = 0, vy = 0;
    let isDragging = false;
    let startX, startY;
    let raf;

    const baseRopeHeight = 130;
    const gravity = 0.5;
    const damping = 0.88;
    const stiffness = 0.08;

    const onDown = e => {
      isDragging = true;
      startX = e.clientX - x;
      startY = e.clientY - y;
      vx = 0; vy = 0;
      e.preventDefault();
    };

    const onMove = e => {
      if (!isDragging) return;
      x = e.clientX - startX;
      y = e.clientY - startY;
    };

    const onUp = () => { isDragging = false; };

    const animate = () => {
      if (!isDragging) {
        vx = vx * damping - x * stiffness;
        vy = vy * damping - y * stiffness + gravity;
        x += vx;
        y += vy;
      }

      card.style.transform = `translate(${x}px, ${y}px) rotate(${x * 0.15}deg)`;
      card.style.transformOrigin = 'top center';

      // rope length — distance from top to card
      const dist = Math.sqrt(x * x + y * y);
      const newHeight = baseRopeHeight + dist * 0.6;
      rope.style.height = `${newHeight}px`;

      // rope angle — follow card
      const angle = Math.atan2(x, Math.max(y + baseRopeHeight, 1)) * (180 / Math.PI);
      rope.style.transform = `rotate(${angle}deg)`;
      rope.style.transformOrigin = 'top center';

      // rope-through follow kare
      if (ropeThrough) {
        ropeThrough.style.transform = `translateX(-50%) rotate(${-angle}deg)`;
      }

      raf = requestAnimationFrame(animate);
    };

    card.addEventListener('mousedown', onDown);
    window.addEventListener('mousemove', onMove);
    window.addEventListener('mouseup', onUp);
    raf = requestAnimationFrame(animate);

    return () => {
      card.removeEventListener('mousedown', onDown);
      window.removeEventListener('mousemove', onMove);
      window.removeEventListener('mouseup', onUp);
      cancelAnimationFrame(raf);
    };
  }, []);

  return (
    <section id="about" className="section reveal" ref={ref}>
      <div className="sec-label">01 — About</div>
      <h2 className="sec-title">Who I Am</h2>

      <div className="about-grid">

        {/* LANYARD */}
        <div className="iwrap">
          <div className="lanyard-wrap" id="lanyardWrap">
            <div className="lanyard-rope">
              <div className="rope-line" />
            </div>
            <div className="id-card" ref={cardRef} id="idCard">
              <div className="card-hole">
                <div className="rope-through" />
              </div>
              <div className="card-img">
                <img
                  src="/images/my pic.jpeg"
                  alt="M Ahmad"
                  onError={e => e.target.style.display = 'none'}
                />
              </div>
              <div className="card-info">
                <span className="card-name">M Ahmad</span>
                <span className="card-role">Full Stack Dev</span>
                <div className="card-badge">
                  <span className="card-dot" />
                  Open to Work
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* TEXT */}
        <div className="about-text">
          <p className="ahi">Junior Full Stack Developer</p>
          <p className="abio">
            Hey! I'm <strong>M Ahmad</strong> — a passionate <strong>Junior Full Stack Developer</strong> who
            recently stepped into web development. I may be a fresher, but I bring <strong>strong dedication,
              curiosity</strong>, and a genuine love for building things that work beautifully.
          </p>
          <p className="abio" style={{ marginTop: '16px' }}>
            On the <strong>frontend</strong>, I work with HTML, CSS, JavaScript, and React. I'm actively
            growing on the <strong>backend</strong> side — learning Node.js, Express &amp; MongoDB to become
            a complete developer.
          </p>
          <p className="abio" style={{ marginTop: '16px' }}>
            I believe every expert was once a beginner. I'm here to <strong>learn fast, build real
              things</strong>, and grow with every project. 🚀
          </p>
          <div className="about-tags">
            {['🎓 Fresh Graduate', '⚡ Fast Learner', '💡 Problem Solver', '🌐 Open to Work'].map(t => (
              <span key={t} className="atag">{t}</span>
            ))}
          </div>
        </div>

      </div>
    </section>
  );
}
